    }): { total: number; dimension: string; unit?: string; displayName: string } {
        const timeBasedUnits = {
            second: {
                60: 'minute',
                3600: 'hour',
                86400: 'day',
            },
            minute: { 60: 'hour', 1440: 'day' },
            hour: { 24: 'day' },
        };
        const dataBasedUnits = {
            byte: {
                1024: 'kibibyte',
