    /**
     * What a dimension's readings add up to over the invoiced period, carried to
     * the two decimal places an invoice is denominated in.
     */
    static billableTotal(usage: AggregatedUsageResponse['usage']): string {
        const total = (usage ?? []).reduce((acc, { value }) => {
            acc += parseFloat(value);
            return acc;
        }, 0);
        return total.toFixed(2).toString();
    }

    /**
     * Usage a customer is charged for on a dimension. Only permitted usage
     * beyond a finite exhausted allowance is billable; an unlimited or
     * unexhausted allowance, or a plan that forbids overage, charges nothing.
     */
    static chargeableQuantity(
        totalUsage: number,
        dimension: { usageEntitlement?: number | 'inf'; overageAllowed?: string },
    ): number {
        const entitlement = dimension?.usageEntitlement;
        if (entitlement === undefined || entitlement === null) {
            return totalUsage;
        }
        if (entitlement === 'inf') {
            return 0;
        }
        if (dimension?.overageAllowed !== overageAllowedEnum.true) {
            return 0;
        }
        const allowance = Number(entitlement);
        if (!Number.isFinite(allowance) || totalUsage <= allowance) {
            return 0;
        }
        return totalUsage - allowance;
